def gen(rng):
    def fmt(B, C, items):
        return f"{len(items)} {B} {C}\n" + "\n".join(f"{c} {t}" for c, t in items)
    tests = [
        fmt(1, 1, [(1, 0)]),
        fmt(1, 1, [(1, 1)]),
        fmt(2, 1, [(1, 1)]),
        fmt(5, 100, [(2, 0), (3, 1)]),
        fmt(10, 3, [(5, 1), (5, 1), (5, 1)]),
        fmt(10 ** 9, 10 ** 9, [(10 ** 9, 1), (1, 0)]),
    ]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for _ in range(3):
            items = [(rng.randint(1, 12), rng.randint(0, 1)) for _ in range(n)]
            tests.append(fmt(rng.randint(1, 40), rng.randint(1, 15), items))
    N = 100000
    for kind in range(4):
        if kind == 0:
            items = [(rng.randint(1, 10 ** 9), rng.randint(0, 1)) for _ in range(N)]
            B, C = 10 ** 13, rng.randint(1, 10 ** 9)
        elif kind == 1:
            items = [(rng.randint(1, 10 ** 9), 1) for _ in range(N)]
            B, C = 10 ** 14, 10 ** 9
        elif kind == 2:
            items = [(rng.randint(1, 1000), rng.randint(0, 1)) for _ in range(N)]
            B, C = 20 * 10 ** 6, 5000
        else:
            items = [(rng.randint(1, 10 ** 6), 0 if rng.random() < 0.9 else 1) for _ in range(N)]
            B, C = 10 ** 14, 10 ** 14 - 1
        tests.append(fmt(B, C, items))
    return tests
